INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('8c9a7997-dbf1-46f4-a02f-982f9a43cc3e', 'b5d63c4f-1cb7-5974-a758-eb342d3ba563', 'de', 'Polnischer Hersteller von Gartensaunen aus Holz und Modulgebäuden. Die Konstruktionen entstehen vollständig in der Halle des Herstellers und werden aus ausgewähltem skandinavischem Holz als fertiges Modul ohne Montage vor Ort zum Kunden geliefert.', NULL, NULL, '2026-10-30T14:06:09.461Z'::timestamptz, '2026-10-30T19:40:54.619Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('50bf7617-6b86-431d-8ee5-9367d0efa464', 'b5d63c4f-1cb7-5974-a758-eb342d3ba563', 'nl', 'Poolse producent van houten tuinsauna''s en modulaire gebouwen. De constructies worden volledig in de werkplaats van de producent gebouwd en uit geselecteerd Scandinavisch hout als kant-en-klare module zonder montage ter plaatse bij de klant geleverd.', NULL, NULL, '2026-10-30T14:06:09.461Z'::timestamptz, '2026-10-30T19:40:54.619Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('79a48a74-a4aa-4cb8-91e3-074d48037d6e', 'b5d63c4f-1cb7-5974-a758-eb342d3ba563', 'en', 'Polish producer of wooden garden saunas and modular buildings. The structures are built entirely in the producer''s workshop and delivered to the customer as a ready-made module, with no on-site assembly, from selected Scandinavian timber.', NULL, NULL, '2026-10-30T14:06:09.461Z'::timestamptz, '2026-10-30T19:40:54.619Z'::timestamptz) ON CONFLICT DO NOTHING;
